const item = $('Get Item Info').first().json;
const descData = $input.first().json;

if (!item || !item.id) {
  return [{ json: { result: 'No se pudo obtener la información del producto. Verificá el ID.' } }];
}

const precio = item.price ? `$${item.price.toLocaleString('es-AR')}` : 'Sin precio';
const precioOriginal = item.original_price && item.original_price > item.price
  ? `$${item.original_price.toLocaleString('es-AR')}` : null;
const descuento = precioOriginal 
  ? `${Math.round((1 - item.price / item.original_price) * 100)}% OFF` : 'Sin descuento';

// Atributos relevantes
const atributos = (item.attributes || [])
  .filter(a => ['BRAND', 'UNITS_PER_PACK', 'NET_WEIGHT', 'FLAVOR'].includes(a.id))
  .map(a => `${a.name}: ${a.value_name}`)
  .join('\n   ');

// Shipping
const shipping = item.shipping?.free_shipping ? 'Envío gratis' : 'Con costo de envío';

// Descripción
const descripcion = descData.plain_text 
  ? descData.plain_text.substring(0, 500) + (descData.plain_text.length > 500 ? '...' : '')
  : 'Sin descripción disponible';

let result = `📍 DETALLE DEL PRODUCTO\n\n`;
result += `📌 Título: ${item.title}\n`;
result += `🏷️ ID: ${item.id}\n`;
result += `💰 Precio: ${precio}`;
if (precioOriginal) result += ` (antes ${precioOriginal} - ${descuento})`;
result += `\n`;
result += `📦 Stock: ${item.available_quantity} unidades\n`;
result += `🚚 ${shipping}\n`;
result += `📊 Estado: ${item.status}\n`;
if (atributos) result += `🏷️ Atributos:\n   ${atributos}\n`;
result += `\n📝 Descripción:\n${descripcion}\n`;
result += `\n🔗 Link: ${item.permalink}`;

return [{ json: { result } }];
